// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "./MeshTypes.sol";

/// @title SAOS Mesh Hub — the sovereign dispatch of the contract chain.
/// @notice One intent, one transaction, seven contracts:
///         Hub → Relay → Identity → Ledger → Solutions → Bridge → Hub →
///         ValueEngine. Every arrow is a real contract-to-contract call.
contract SAOSMeshHub {
    address public owner;
    IRelayStart public relay;
    IValueFinalize public valueEngine;

    enum Status { Open, Completed }
    struct Run {
        address initiator;
        string intent;
        uint64 startedAt;
        uint64 completedAt;
        Status status;
    }
    mapping(uint256 => Run) public runs;
    uint256 public runCount;
    uint256 public completedCount;
    uint256 public totalGasUsed;

    event RunDispatched(uint256 indexed runId, address indexed initiator, string intent);
    event RunCompleted(uint256 indexed runId, uint256 gasUsed, uint256 score, uint64 duration);

    error NotOwner();
    error NotRelay();
    error AlreadyCompleted();

    constructor() { owner = msg.sender; }

    function wire(address relayAddr, address valueEngineAddr) external {
        if (msg.sender != owner) revert NotOwner();
        relay = IRelayStart(relayAddr);
        valueEngine = IValueFinalize(valueEngineAddr);
    }

    /// @dev Entry point of the mesh: dispatch a run through the whole chain.
    function dispatch(string calldata intent) external returns (uint256 runId) {
        runId = ++runCount;
        runs[runId] = Run(msg.sender, intent, uint64(block.timestamp), 0, Status.Open);
        emit RunDispatched(runId, msg.sender, intent);
        relay.start(runId, abi.encode(msg.sender, intent));
        return runId;
    }

    /// @dev Called by the relay when every link has processed the run.
    function complete(uint256 runId, uint256 gasUsed) external {
        if (msg.sender != address(relay)) revert NotRelay();
        Run storage r = runs[runId];
        if (r.status == Status.Completed) revert AlreadyCompleted();
        r.status = Status.Completed;
        r.completedAt = uint64(block.timestamp);
        completedCount += 1;
        totalGasUsed += gasUsed;
        uint256 score = valueEngine.finalize(runId, gasUsed);
        emit RunCompleted(runId, gasUsed, score, r.completedAt - r.startedAt);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "./MeshTypes.sol";

/// @title SAOS Mesh Relay — the switchboard: routes each run through the
///        ordered chain of links, hop by hop, and measures the gas trail.
/// @notice דבר מוביל לדבר: each link calls pass() and the message jumps to
///         the NEXT contract. When the chain is exhausted the hub completes.
contract SAOSMeshRelay {
    address public owner;
    IHubComplete public hub;
    address[] public links;

    mapping(uint256 => uint256) public cursor;   // runId → next link index
    mapping(uint256 => uint256) public startGas; // runId → gas at chain start

    event Hop(uint256 indexed runId, uint256 indexed index, address indexed link, uint256 gasBefore);

    error NotOwner();
    error NotHub();
    error NotActiveLink();

    constructor() { owner = msg.sender; }

    function wireHub(address hubAddr) external {
        if (msg.sender != owner) revert NotOwner();
        hub = IHubComplete(hubAddr);
    }

    function addLink(address link) external {
        if (msg.sender != owner) revert NotOwner();
        links.push(link);
    }

    function linkCount() external view returns (uint256) { return links.length; }

    /// @dev The hub starts the chain here.
    function start(uint256 runId, bytes calldata context) external {
        if (msg.sender != address(hub)) revert NotHub();
        startGas[runId] = gasleft();
        cursor[runId] = 0;
        _pass(runId, context);
    }

    /// @dev The link that just processed the run continues the chain.
    function pass(uint256 runId, bytes calldata context) external {
        uint256 i = cursor[runId];
        if (i == 0 || i > links.length || links[i - 1] != msg.sender) revert NotActiveLink();
        _pass(runId, context);
    }

    function _pass(uint256 runId, bytes memory context) internal {
        uint256 i = cursor[runId];
        if (i >= links.length) {
            hub.complete(runId, startGas[runId] - gasleft());
            return;
        }
        address link = links[i];
        cursor[runId] = i + 1;
        emit Hop(runId, i, link, gasleft());
        IMeshLink(link).process(runId, context);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "./MeshTypes.sol";

/// @title SAOS Identity — the sovereign agent registry (mesh link #1).
/// @notice Every initiator is auto-enlisted on its first run — the mesh
///         onboards its own agents. The real fleet EVM identities are also
///         registered here by the operator (public addresses only).
contract SAOSIdentity {
    address public owner;
    address public relay;

    struct Agent { address addr; string handle; uint64 joinedAt; uint64 runs; }
    Agent[] private _agents;
    mapping(address => uint256) private _indexPlusOne; // 0 = unknown

    event AgentRegistered(uint256 indexed agentIndex, address indexed agent, string handle);
    event IdentityStamped(uint256 indexed runId, address indexed initiator, uint256 agentIndex, uint64 totalRuns);

    error NotOwner();
    error NotRelay();

    constructor() { owner = msg.sender; }

    function wire(address relayAddr) external {
        if (msg.sender != owner) revert NotOwner();
        relay = relayAddr;
    }

    function register(address agent, string calldata handle) external {
        if (msg.sender != owner) revert NotOwner();
        _register(agent, handle);
    }

    function _register(address agent, string memory handle) internal {
        if (_indexPlusOne[agent] != 0) return; // idempotent
        _agents.push(Agent(agent, handle, uint64(block.timestamp), 0));
        _indexPlusOne[agent] = _agents.length;
        emit AgentRegistered(_agents.length - 1, agent, handle);
    }

    function agentCount() external view returns (uint256) { return _agents.length; }
    function agentAt(uint256 i) external view returns (Agent memory) { return _agents[i]; }

    function process(uint256 runId, bytes calldata context) external returns (bytes memory) {
        if (msg.sender != relay) revert NotRelay();
        (address initiator, ) = abi.decode(context, (address, string));
        uint256 idxPlus = _indexPlusOne[initiator];
        uint256 idx;
        if (idxPlus == 0) {
            string memory handle = string(abi.encodePacked("SAOS-", _itoa(_agents.length)));
            _agents.push(Agent(initiator, handle, uint64(block.timestamp), 1));
            idx = _agents.length - 1;
            _indexPlusOne[initiator] = _agents.length;
            emit AgentRegistered(idx, initiator, handle);
        } else {
            idx = idxPlus - 1;
            _agents[idx].runs += 1;
        }
        emit IdentityStamped(runId, initiator, idx, _agents[idx].runs);
        IRelayPass(relay).pass(runId, context);
        return context;
    }

    function _itoa(uint256 v) internal pure returns (string memory) {
        if (v == 0) return "0";
        uint256 x = v;
        uint256 d;
        while (x != 0) { d++; x /= 10; }
        bytes memory b = new bytes(d);
        x = v;
        while (x != 0) { b[--d] = bytes1(uint8(48 + x % 10)); x /= 10; }
        return string(b);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "./MeshTypes.sol";

/// @title SAOS Ledger — the zero-fee internal value rail (mesh link #2).
/// @notice ללא עמלה — the fee is a compile-time zero, forever. Every mesh
///         run mints a small sovereign reward (mint קטן) to the initiating
///         agent, and internal transfers never pay anything.
///         v2 — payroll: every run also mints the same reward to the work
///         board (set by the owner), so the HQ can always pay its soldiers
///         through the zero-fee rail. עבודה ממומנת: mint קטן לחייל + mint
///         קטן לקופת העבודה — בכל ריצה.
contract SAOSLedger {
    address public owner;
    address public relay;
    address public payroll; // the SAOSWorkBoard — funded by every run

    string public constant SYMBOL = "SAOS-M";
    uint256 public constant RUN_REWARD = 10 ether; // 10 SAOS-M per run (small mint)
    uint256 public constant FEE = 0;               // forever zero — by construction

    mapping(address => uint256) public balanceOf;
    uint256 public totalSupply;
    uint256 public runMinted;
    uint256 public transfersCount;
    uint256 public valueMoved;

    event RewardPaid(uint256 indexed runId, address indexed to, uint256 amount);
    event PayrollFunded(uint256 indexed runId, address indexed payroll, uint256 amount);
    event ZeroFeeTransfer(uint256 indexed seq, address indexed from, address indexed to, uint256 amount, uint256 fee);

    error NotOwner();
    error NotRelay();
    error InsufficientBalance();

    constructor() { owner = msg.sender; }

    function wire(address relayAddr) external {
        if (msg.sender != owner) revert NotOwner();
        relay = relayAddr;
    }

    /// @dev v2 — the work board's payroll address (owner-only, one-time).
    function setPayroll(address payrollAddr) external {
        if (msg.sender != owner) revert NotOwner();
        payroll = payrollAddr;
    }

    function process(uint256 runId, bytes calldata context) external returns (bytes memory) {
        if (msg.sender != relay) revert NotRelay();
        (address initiator, ) = abi.decode(context, (address, string));
        balanceOf[initiator] += RUN_REWARD;
        totalSupply += RUN_REWARD;
        runMinted += RUN_REWARD;
        emit RewardPaid(runId, initiator, RUN_REWARD);
        if (payroll != address(0)) {
            balanceOf[payroll] += RUN_REWARD;
            totalSupply += RUN_REWARD;
            runMinted += RUN_REWARD;
            emit PayrollFunded(runId, payroll, RUN_REWARD);
        }
        IRelayPass(relay).pass(runId, context);
        return context;
    }

    /// @dev Sovereign internal transfer — zero fee, forever.
    function transfer(address to, uint256 amount) external returns (bool) {
        if (balanceOf[msg.sender] < amount) revert InsufficientBalance();
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        transfersCount += 1;
        valueMoved += amount;
        emit ZeroFeeTransfer(transfersCount, msg.sender, to, amount, FEE);
        return true;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "./MeshTypes.sol";

/// @title SAOS Solutions — every mesh run commits a solution on-chain
///        (mesh link #3): פתרונות. Identity → value → solution: the run
///        itself becomes a durable, hash-committed artifact.
contract SAOSSolutions {
    address public owner;
    address public relay;

    struct Solution { uint256 runId; address agent; string title; bytes32 digest; uint64 at; }
    Solution[] private _solutions;

    event SolutionCommitted(uint256 indexed solutionId, uint256 indexed runId, address indexed agent, string title, bytes32 digest);

    error NotOwner();
    error NotRelay();

    constructor() { owner = msg.sender; }

    function wire(address relayAddr) external {
        if (msg.sender != owner) revert NotOwner();
        relay = relayAddr;
    }

    function solutionCount() external view returns (uint256) { return _solutions.length; }
    function solutionAt(uint256 i) external view returns (Solution memory) { return _solutions[i]; }

    function process(uint256 runId, bytes calldata context) external returns (bytes memory) {
        if (msg.sender != relay) revert NotRelay();
        (address initiator, string memory intent) = abi.decode(context, (address, string));
        bytes32 digest = keccak256(abi.encodePacked(runId, initiator, intent, block.number, block.timestamp));
        _solutions.push(Solution(runId, initiator, intent, digest, uint64(block.timestamp)));
        emit SolutionCommitted(_solutions.length - 1, runId, initiator, intent, digest);
        IRelayPass(relay).pass(runId, context);
        return context;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "./MeshTypes.sol";

/// @title SAOS Bridge — stamps the 8-chain grid state into every mesh run
///        (mesh link #4): the EXTERNAL network state (SAOS-NET, STEEM,
///        BLURT, HIVE, TRON, ETHEREUM, BSC, SOLANA) flows INTO the contract
///        mesh — the whole organism is anchored inside every run.
contract SAOSBridge {
    address public owner;
    address public relay;

    struct Anchor { string chain; uint256 height; bytes32 digest; uint64 at; }
    string[] private _chains;
    mapping(string => Anchor) private _latest;

    event ChainRegistered(string chain);
    event ExternalAnchored(string chain, uint256 height, bytes32 digest);
    event AnchorStamped(uint256 indexed runId, string chain, uint256 height, bytes32 digest);

    error NotOwner();
    error NotRelay();
    error UnknownChain();

    constructor() { owner = msg.sender; }

    function wire(address relayAddr) external {
        if (msg.sender != owner) revert NotOwner();
        relay = relayAddr;
    }

    function registerChain(string calldata chain) external {
        if (msg.sender != owner) revert NotOwner();
        if (_latest[chain].at != 0) return; // idempotent
        _chains.push(chain);
        _latest[chain] = Anchor(chain, 0, 0, uint64(block.timestamp));
        emit ChainRegistered(chain);
    }

    function chainCount() external view returns (uint256) { return _chains.length; }
    function chains() external view returns (string[] memory) { return _chains; }
    function latestAnchor(string calldata chain) external view returns (Anchor memory) { return _latest[chain]; }

    /// @dev The operator (mesh backend) pushes LIVE external heights in.
    function anchorExternal(string calldata chain, uint256 height, bytes32 digest) external {
        if (msg.sender != owner) revert NotOwner();
        Anchor storage a = _latest[chain];
        if (a.at == 0) revert UnknownChain();
        a.height = height;
        a.digest = digest;
        a.at = uint64(block.timestamp);
        emit ExternalAnchored(chain, height, digest);
    }

    /// @dev Bulk anchor refresh — one transaction, all rails at once.
    function anchorExternalBulk(
        string[] calldata chainList,
        uint256[] calldata heights,
        bytes32[] calldata digests
    ) external {
        if (msg.sender != owner) revert NotOwner();
        require(chainList.length == heights.length && chainList.length == digests.length, "SAOS: length mismatch");
        for (uint256 i = 0; i < chainList.length; i++) {
            Anchor storage a = _latest[chainList[i]];
            if (a.at == 0) continue; // not registered — skip honestly
            a.height = heights[i];
            a.digest = digests[i];
            a.at = uint64(block.timestamp);
            emit ExternalAnchored(chainList[i], heights[i], digests[i]);
        }
    }

    function process(uint256 runId, bytes calldata context) external returns (bytes memory) {
        if (msg.sender != relay) revert NotRelay();
        for (uint256 i = 0; i < _chains.length; i++) {
            Anchor memory a = _latest[_chains[i]];
            emit AnchorStamped(runId, a.chain, a.height, a.digest);
        }
        IRelayPass(relay).pass(runId, context);
        return context;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "./MeshTypes.sol";

/// @title SAOS Work Board — פקודות עבודה (mesh link #5): HQ posts work,
///        soldiers deliver it, the ledger pays — all inside the mesh run.
/// @notice עבודה לחיילים: every mesh run is now WORK. The HQ (owner)
///         posts open orders with a mission, difficulty and reward. The
///         board is a mesh link — when a run reaches it, the run's
///         initiator (a soldier) delivers the oldest open order, and the
///         reward moves through the zero-fee ledger rail (payroll balance
///         is minted to the board on every run by SAOSLedger).
///         פתרונות · ערך · יעילות — solutions, pay and efficiency in
///         ONE chained transaction: Hub → Relay → Identity → Ledger →
///         Solutions → Bridge → **WorkBoard** → Hub → ValueEngine.
contract SAOSWorkBoard {
    address public owner;
    address public relay;
    ILedgerRail public ledger;

    enum Status { Open, Delivered }

    struct Order {
        string mission;       // the work: what the soldier must do
        uint256 difficulty;   // 1..5 — complexity level
        uint256 reward;       // SAOS-M, zero-fee, paid from the payroll
        Status status;
        address soldier;      // assigned on delivery
        uint256 runId;        // the mesh run that delivered this order
        uint64 postedAt;
        uint64 deliveredAt;
        bool paid;            // honest: reward actually moved
    }
    Order[] private _orders;

    struct SoldierStat { address soldier; uint256 orders; uint256 earned; }
    mapping(address => uint256) private _soldierIndexPlusOne; // 0 = not yet
    SoldierStat[] private _soldiers;

    uint256 public ordersDelivered;
    uint256 public totalRewardPaid;

    event OrderPosted(uint256 indexed orderId, string mission, uint256 difficulty, uint256 reward);
    event OrderDelivered(uint256 indexed orderId, uint256 indexed runId, address indexed soldier, string mission, uint256 reward, bool paid);

    error NotOwner();
    error NotRelay();
    error OrderOutOfBounds();

    constructor() { owner = msg.sender; }

    function wire(address relayAddr, address ledgerAddr) external {
        if (msg.sender != owner) revert NotOwner();
        relay = relayAddr;
        ledger = ILedgerRail(ledgerAddr);
    }

    /// @dev HQ posts a new work order. Payroll must be able to cover it
    ///      (escrow discipline) — checked at delivery, never blocks the run.
    function postOrder(string calldata mission, uint256 difficulty, uint256 reward) external returns (uint256 orderId) {
        if (msg.sender != owner) revert NotOwner();
        _orders.push(Order(mission, difficulty, reward, Status.Open, address(0), 0, uint64(block.timestamp), 0, false));
        orderId = _orders.length - 1;
        emit OrderPosted(orderId, mission, difficulty, reward);
        return orderId;
    }

    function orderCount() external view returns (uint256) { return _orders.length; }

    function orderAt(uint256 i) external view returns (Order memory) {
        if (i >= _orders.length) revert OrderOutOfBounds();
        return _orders[i];
    }

    function soldierCount() external view returns (uint256) { return _soldiers.length; }

    function soldierAt(uint256 i) external view returns (SoldierStat memory) {
        if (i >= _soldiers.length) revert OrderOutOfBounds();
        return _soldiers[i];
    }

    /// @dev mesh link #5 — the run's initiator delivers the oldest open order
    ///      and gets paid through the zero-fee rail. If the payroll cannot
    ///      cover the reward the delivery is recorded but unpaid (honest
    ///      flag) — the chain NEVER breaks over money.
    function process(uint256 runId, bytes calldata context) external returns (bytes memory) {
        if (msg.sender != relay) revert NotRelay();
        (address initiator, ) = abi.decode(context, (address, string));
        uint256 orderId = _oldestOpen();
        if (orderId != type(uint256).max) {
            Order storage o = _orders[orderId];
            o.status = Status.Delivered;
            o.soldier = initiator;
            o.runId = runId;
            o.deliveredAt = uint64(block.timestamp);
            ordersDelivered += 1;
            // pay through the zero-fee ledger rail — only if funded
            bool paid = false;
            if (address(ledger) != address(0) && ledger.balanceOf(address(this)) >= o.reward && o.reward > 0) {
                ledger.transfer(initiator, o.reward);
                paid = true;
                totalRewardPaid += o.reward;
            }
            o.paid = paid;
            _bump(initiator, paid ? o.reward : 0);
            emit OrderDelivered(orderId, runId, initiator, o.mission, o.reward, paid);
        }
        IRelayPass(relay).pass(runId, context);
        return context;
    }

    function _oldestOpen() internal view returns (uint256) {
        for (uint256 i = 0; i < _orders.length; i++) {
            if (_orders[i].status == Status.Open) return i;
        }
        return type(uint256).max;
    }

    function _bump(address soldier, uint256 paid) internal {
        uint256 ipo = _soldierIndexPlusOne[soldier];
        if (ipo == 0) {
            _soldiers.push(SoldierStat(soldier, 1, paid));
            _soldierIndexPlusOne[soldier] = _soldiers.length;
        } else {
            SoldierStat storage s = _soldiers[ipo - 1];
            s.orders += 1;
            s.earned += paid;
        }
    }
}

/// @dev the zero-fee value rail the board pays through (SAOSLedger).
interface ILedgerRail {
    function balanceOf(address who) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "./MeshTypes.sol";

/// @title SAOS Value Engine — efficiency & value scoring: ערך · יעילות.
/// @dev score = (BASE + HOP_VALUE × hops)² / (gasUsed/GAS_DIV + 1) —
///      denser value per gas unit earns a higher sovereign score. Every
///      completed run is scored; aggregates track the mesh economy.
contract SAOSValueEngine {
    address public owner;
    address public hub;
    address public relay;

    uint256 public constant BASE = 1000;      // base value units
    uint256 public constant HOP_VALUE = 250;  // value units per mesh hop
    uint256 public constant GAS_DIV = 1000;   // gas normalization divisor

    struct Score { uint256 gasUsed; uint256 hops; uint256 score; uint64 at; }
    mapping(uint256 => Score) public scores;

    uint256 public scoredRuns;
    uint256 public totalScore;
    uint256 public totalGas;
    uint256 public bestScore;

    event ValueScored(uint256 indexed runId, uint256 score, uint256 gasUsed, uint256 hops);

    error NotOwner();
    error NotHub();

    constructor() { owner = msg.sender; }

    function wire(address hubAddr, address relayAddr) external {
        if (msg.sender != owner) revert NotOwner();
        hub = hubAddr;
        relay = relayAddr;
    }

    function efficiencyOf(uint256 hops, uint256 gasUsed) public pure returns (uint256) {
        uint256 value = (BASE + HOP_VALUE * hops) * (BASE + HOP_VALUE * hops);
        return value / (gasUsed / GAS_DIV + 1);
    }

    function finalize(uint256 runId, uint256 gasUsed) external returns (uint256) {
        if (msg.sender != hub) revert NotHub();
        uint256 hops = IRelayLinkCount(relay).linkCount();
        uint256 score = efficiencyOf(hops, gasUsed);
        scores[runId] = Score(gasUsed, hops, score, uint64(block.timestamp));
        scoredRuns += 1;
        totalScore += score;
        totalGas += gasUsed;
        if (score > bestScore) bestScore = score;
        emit ValueScored(runId, score, gasUsed, hops);
        return score;
    }

    function averageScore() external view returns (uint256) {
        return scoredRuns == 0 ? 0 : totalScore / scoredRuns;
    }
}
